-- Additive exact G1/4109409 supplement. Original six registries/receipts stay separate.
create schema private_fcf_g1_supplement;
revoke all on schema private_fcf_g1_supplement from public,anon,authenticated,service_role;
create function private_fcf_g1_supplement.policy()returns jsonb language sql immutable set search_path=pg_catalog,pg_temp as $$select '{"schemaVersion":1,"id":"es-ct-segona-g1-supplement-4109409-v1","provider":"fcf","competitionSlug":"es-ct-segona-g1","competitionId":783,"season":"2026/27","approvalReference":"call_7602c249643b4d43b097457adf63e128","approvedOriginalSha256":"b3737490800a28588fbc4b6eb1d06b26913dcb31149b5ee82a7ae96379d69871","approvedOriginalBytes":171201,"reasonCode":"closed_official_result_and_individual_statistics_unavailable","fixture":{"sourceMatchId":"4109409","sourceCompetitionId":null,"sourcePhase":null,"sourceRound":3,"playedOn":"2026-10-04","kickoff":"17:00","season":"2026/27","homeSourceClubId":"21434932","homeSourceCategoryId":"21442320","awaySourceClubId":"5002","awaySourceCategoryId":"37524","sourceUrl":"https://www.fcf.cat/ca/competicio/acta/4109409","observedHomeScore":null,"observedAwayScore":null},"homeName":"EMPURIABRAVA CASTELLO, C.F.","awayName":"BANYOLES, C.E.","goalEventCount":0}'::jsonb$$;
create table private_fcf_g1_supplement.markers(
 match_id bigint primary key references public.matches(id),round_id bigint not null references public.rounds(id),home_team_id bigint not null references public.teams(id),away_team_id bigint not null references public.teams(id),binding jsonb not null,before_image_text text not null,before_sha256 text not null check(before_sha256=encode(sha256(convert_to(before_image_text,'UTF8')),'hex')),authorized_xid bigint not null,installed_at timestamptz not null default clock_timestamp(),singleton boolean not null unique default true check(singleton)
);
create table private_fcf_g1_supplement.receipts(
 match_id bigint primary key references private_fcf_g1_supplement.markers(match_id),after_image jsonb not null,receipt jsonb not null
);
create function private_fcf_g1_supplement.immutable()returns trigger language plpgsql as $$begin raise exception 'FCF_G1_SUPPLEMENT: immutable marker/receipt';end$$;
create trigger immutable before update or delete on private_fcf_g1_supplement.markers for each row execute function private_fcf_g1_supplement.immutable();
create trigger immutable before update or delete on private_fcf_g1_supplement.receipts for each row execute function private_fcf_g1_supplement.immutable();
create function public.get_installed_fcf_g1_supplement()returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare s jsonb;begin
 select binding into s from private_fcf_g1_supplement.markers;if s is null then return 'null'::jsonb;end if;
 perform private_fcf_g1_supplement.readback(s);
 return(select jsonb_build_object('binding',m.binding,'afterImage',r.after_image,'receipt',r.receipt)from private_fcf_g1_supplement.markers m join private_fcf_g1_supplement.receipts r using(match_id));
end$$;
create function private_fcf_g1_supplement.exact_match(m public.matches)returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from private_fcf_g1_supplement.markers s join rounds r on r.id=s.round_id where s.match_id=m.id and s.round_id=m.round_id and s.home_team_id=m.home_team_id and s.away_team_id=m.away_team_id and r.competition_id=783 and r.season='2026/27'and r.number=3 and s.binding->>'policySha256'='a9141400858c80322b6cb12b13c54a5dde45e93f080b4fe0b644dce513657ee7'and s.binding->'fixture'=private_fcf_g1_supplement.policy()->'fixture'and m.zapisnik_id='es4109409'and m.source_url='https://www.fcf.cat/ca/competicio/acta/4109409'and m.played_on='2026-10-04'and m.statistics_status='unavailable_historical'and m.statistics_reason='closed_official_result_and_individual_statistics_unavailable'and m.source_phase is null and m.source_round=3 and m.home_goals is null and m.away_goals is null and m.imported_at is null and not m.kontumacija and not m.vir_brez_izida and cardinality(m.import_warnings)=0);
$$;
alter table public.matches drop constraint paired_result_availability;
alter table public.matches add constraint paired_result_availability check((home_goals is not null and away_goals is not null)or(home_goals is null and away_goals is null and(private_fcf_six_history.unknown_result_allowed(round_id,home_team_id,away_team_id,zapisnik_id,source_url,played_on,statistics_status,statistics_reason,source_phase,source_round)is true or private_fcf_g1_supplement.exact_match(matches)is true)));


create or replace function private_historical_statistics.protect_match()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare mk private_historical_statistics.markers%rowtype;e jsonb;
begin
 if tg_op in('UPDATE','DELETE')and exists(select 1 from private_fcf_g1_supplement.markers where match_id=old.id and not(authorized_xid=txid_current()and old.statistics_status='available'))then
  if tg_op='DELETE'or to_jsonb(old)is distinct from to_jsonb(new)then raise exception 'FCF_G1_SUPPLEMENT: installed match immutable';end if;
 end if;
 if tg_op<>'DELETE'and new.zapisnik_id='es4109409'and new.statistics_status='unavailable_historical'then
  if private_fcf_g1_supplement.exact_match(new)is not true or exists(select 1 from appearances where match_id=new.id)or exists(select 1 from goals where match_id=new.id)then raise exception 'FCF_G1_SUPPLEMENT: exact empty installed native marker required';end if;
  return new;
 end if;
 if tg_op in('UPDATE','DELETE')and old.zapisnik_id in('es4109388','es4109404','es4116215','es4118352','es4118354','es4118358')and exists(select 1 from private_fcf_six_history.restore_authorizations where authorized_xid=txid_current())then if tg_op='DELETE'then return old;else return new;end if;end if;
 if tg_op='DELETE'then
  if old.statistics_status='unavailable_historical'then raise exception 'HISTORICAL_POLICY: installed marker immutable';end if;return old;
 end if;
 if tg_op='UPDATE'and old.statistics_status='unavailable_historical'and to_jsonb(old)is distinct from to_jsonb(new)then raise exception 'HISTORICAL_POLICY: installed marker immutable';end if;
 if new.statistics_status='unavailable_historical'then
  select k.* into mk from private_historical_statistics.markers k where k.round_id=new.round_id and k.home_team_id=new.home_team_id and k.away_team_id=new.away_team_id and k.source_report_id=new.zapisnik_id;
  select value into e from private_historical_statistics.installed_policies i join private_historical_statistics.policies p on p.id=i.policy_id cross join lateral jsonb_array_elements(p.document->'entries')where i.competition_id=mk.competition_id and value->>'sourceMatchId'=mk.source_match_id;
  if mk.source_match_id is null or new.imported_at is not null or new.kontumacija or new.vir_brez_izida or new.played_on is distinct from(mk.fixture->>'playedOn')::date or new.home_goals is distinct from(mk.fixture->>'observedHomeScore')::int
  or new.away_goals is distinct from(mk.fixture->>'observedAwayScore')::int or new.source_url is distinct from mk.fixture->>'sourceUrl' or new.statistics_reason is distinct from e->>'reasonCode'
  or new.source_phase is distinct from mk.fixture->>'sourcePhase' or new.source_round is distinct from(mk.fixture->>'sourceRound')::int
  or exists(select 1 from public.appearances where match_id=new.id)or exists(select 1 from public.goals where match_id=new.id)
  then raise exception 'HISTORICAL_POLICY: unavailable match requires exact empty installed marker';end if;
 end if;return new;
end $$;


create function private_fcf_g1_supplement.individual_guard()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin
 if exists(select 1 from private_fcf_g1_supplement.markers where match_id=new.match_id)then raise exception 'FCF_G1_SUPPLEMENT: individual statistics unavailable';end if;return new;
end$$;
create trigger fcf_g1_supplement_individual before insert or update on public.appearances for each row execute function private_fcf_g1_supplement.individual_guard();
create trigger fcf_g1_supplement_individual before insert or update on public.goals for each row execute function private_fcf_g1_supplement.individual_guard();


