 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(l,array['sourceCommit','planSha256','runId','runAttempt','rulesetId','completedUTC','conclusion','claimBinding','consumptionBinding','child','unstartedBinding','finalReceiptBinding'])and l->>'sourceCommit'='ec3405898b628f9e88b7a2908f5f21881ceb836f'and l->>'runId'='40675710752'and l->>'runAttempt'='1'and l->>'conclusion'='failure'and(l->>'completedUTC')::timestamptz<=clock_timestamp()and l->'unstartedBinding'='null'::jsonb and l->>'planSha256'~'^[a-f0-9]{64}$'and l->>'rulesetId'~'^[1-9][0-9]*$','genuine failed G1 terminal execution');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(q,array['claimRef','claimCommit','claimJsonSha256'])and q->>'claimRef'='refs/tags/fcf-inventory-claim/future-after-'||encode(sha256(convert_to(private_fcf_future_import.canonical_json(prior),'UTF8')),'hex')and q->>'claimCommit'='7099f34fee02e2b42688ee054630d3424788e9d4'and q->>'claimJsonSha256'~'^[a-f0-9]{64}$','old G1 consumed protected claim');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(ch,array['targetSlug','planSha256','sourceCommit','runId','runAttempt','claimCommit','priorSourceGETs','status','newSourceGETs','actualSourceGETs','firstSourceUTC','lastCompletedUTC','stopReason','inventoryBinding','auditBinding'])and ch->>'targetSlug'='es-ct-segona-g1'and ch->>'planSha256'=l->>'planSha256'and ch->>'sourceCommit'=l->>'sourceCommit'and ch->>'runId'=l->>'runId'and ch->>'runAttempt'='1'and ch->>'claimCommit'=q->>'claimCommit'and ch->'priorSourceGETs'='38'::jsonb and ch->'newSourceGETs'='22'::jsonb and ch->'actualSourceGETs'='60'::jsonb and ch->>'status'='failed'and ch->'auditBinding'='null'::jsonb and ch#>>'{inventoryBinding,artifactId}'='12812020476','genuine failed diagnostic22 counted');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(l->'consumptionBinding',array['artifactId','artifactDigest','manifestSha256','runId','runAttempt','jobId','claimRef','claimCommit','claimJsonSha256'])and((l->'consumptionBinding')-array['artifactId','artifactDigest','manifestSha256','runId','runAttempt','jobId'])=q,'old G1 exact consumption claim');
 for q in select l->'consumptionBinding'union all select l->'finalReceiptBinding'union all select ch->'inventoryBinding'loop
  perform private_fcf_six_target_release.require(q->>'artifactId'~'^[1-9][0-9]*$'and q->>'artifactDigest'~'^sha256:[a-f0-9]{64}$'and q->>'manifestSha256'~'^[a-f0-9]{64}$'and q->>'runId'=l->>'runId'and q->>'runAttempt'='1'and q->>'jobId'~'^[1-9][0-9]*$','old G1 complete actual artifact bindings');
 end loop;
 for q in select l->'finalReceiptBinding'union all select ch->'inventoryBinding'loop
  perform private_fcf_six_target_release.require(private_fcf_future_import.keys(q,array['artifactId','artifactDigest','runId','runAttempt','jobId','retentionCommit','manifestSha256'])and q->>'retentionCommit'=l->>'sourceCommit','old G1 retained source execution');
 end loop;
end$$;


create or replace function private_fcf_future_import.source_binding(b jsonb)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare q jsonb;a jsonb;hashes jsonb;begin
 select jsonb_object_agg(document->>'competitionSlug',policy_sha256)into hashes from private_historical_statistics.policies where document->>'sourcePolicy'='es-fcf-six-reviewed-history-v1';
 if b->>'protocol'='future-g1-after-failed-g1-v1'then
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(b,array['schemaVersion','kind','protocol','targetSlug','sourceCommit','planSha256','childPlanSha256','sourceClaimState','maximumSourceGETs','priorSourceGETs','newSourceGETs','actualSourceGETs','accountingBinding','claimBinding','consumptionBinding','inventoryBinding','auditBinding','finalReceiptBinding','policyHashes','sourceFingerprintSha256','supplementalPolicySha256','cleanupIssuerSourceCommit'])and b->'schemaVersion'='1'::jsonb and b->>'kind'='fcf-future-source-admission'and b->>'targetSlug'='es-ct-segona-g1'and b->>'sourceCommit'~'^[a-f0-9]{40}$'and b->>'planSha256'~'^[a-f0-9]{64}$'and b->>'childPlanSha256'~'^[a-f0-9]{64}$'and b->>'sourceFingerprintSha256'~'^[a-f0-9]{64}$'and b->>'sourceClaimState'='consumed'and b->'priorSourceGETs'='60'::jsonb and b->'newSourceGETs'='240'::jsonb and b->'actualSourceGETs'='300'::jsonb and b->'maximumSourceGETs'='478'::jsonb and b->'policyHashes'=hashes and b->>'supplementalPolicySha256'='a9141400858c80322b6cb12b13c54a5dde45e93f080b4fe0b644dce513657ee7','closed post-failed G1 60/240/300/478 supplemental source');
 a:=b->'accountingBinding';perform private_fcf_g1_supplement.post_g1_history(a);
 perform private_fcf_six_target_release.require(b->>'cleanupIssuerSourceCommit'=a#>>'{priorAccountingBinding,latest,sourceCommit}'and b->>'sourceCommit'not in(a#>>'{latest,sourceCommit}',b->>'cleanupIssuerSourceCommit'),'authenticated G9 ancestor/new final source writer');
 elsif b->>'protocol'='future-g1-after-g9-v1' then
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(b,array['schemaVersion','kind','protocol','targetSlug','sourceCommit','planSha256','childPlanSha256','sourceClaimState','maximumSourceGETs','priorSourceGETs','newSourceGETs','actualSourceGETs','accountingBinding','claimBinding','consumptionBinding','inventoryBinding','auditBinding','finalReceiptBinding','policyHashes','sourceFingerprintSha256'])and b->>'schemaVersion'='1'and b->>'kind'='fcf-future-source-admission'and b->>'targetSlug'='es-ct-segona-g1'and b->>'sourceCommit'~'^[a-f0-9]{40}$'and b->>'planSha256'~'^[a-f0-9]{64}$'and b->>'childPlanSha256'~'^[a-f0-9]{64}$'and b->>'sourceFingerprintSha256'~'^[a-f0-9]{64}$'and b->>'sourceClaimState'='consumed'and b->>'newSourceGETs'='240'and b->>'maximumSourceGETs'='478'and b->'policyHashes'=hashes,'closed G1 actual-history/fresh240/478 source tuple');
 a:=b->'accountingBinding';perform private_fcf_future_import.post_g9_history(a);
 perform private_fcf_six_target_release.require(b->'priorSourceGETs'=a->'priorSourceGETs'and jsonb_typeof(b->'actualSourceGETs')='number'and(b->>'actualSourceGETs')::numeric=(a->>'priorSourceGETs')::numeric+240 and(b->>'actualSourceGETs')::numeric<=478,'G1 actual prior plus240 remains within478');
 else
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(b,array['schemaVersion','kind','protocol','targetSlug','sourceCommit','planSha256','childPlanSha256','sourceClaimState','maximumSourceGETs','priorSourceGETs','newSourceGETs','actualSourceGETs','accountingBinding','claimBinding','consumptionBinding','inventoryBinding','auditBinding','finalReceiptBinding','policyHashes','sourceFingerprintSha256'])and b->>'schemaVersion'='1'and b->>'kind'='fcf-future-source-admission'and b->>'protocol'='future-g9-after-six-v1'and b->>'targetSlug'='es-ct-tercera-g9'and b->>'sourceCommit'~'^[a-f0-9]{40}$'and b->>'planSha256'~'^[a-f0-9]{64}$'and b->>'childPlanSha256'~'^[a-f0-9]{64}$'and b->>'sourceFingerprintSha256'~'^[a-f0-9]{64}$'and b->>'sourceClaimState'='consumed'and b->>'priorSourceGETs'='37'and b->>'newSourceGETs'='240'and b->>'actualSourceGETs'='277'and b->>'maximumSourceGETs'='478'and b->'policyHashes'=hashes,'closed authenticated future37/240/277/478 source tuple');
 a:=b->'accountingBinding';
 perform private_fcf_future_import.post_six_accounting(a);
 end if;
 q:=b->'claimBinding';
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(q,array['claimRef','claimCommit','claimJsonSha256'])and q->>'claimRef'=case when b->>'protocol'='future-g1-after-failed-g1-v1'then 'refs/tags/fcf-inventory-claim/g1-after-failed-'when b->>'protocol'='future-g1-after-g9-v1'then 'refs/tags/fcf-inventory-claim/future-after-'else 'refs/tags/fcf-inventory-claim/future-g9-after-'end||encode(sha256(convert_to(private_fcf_future_import.canonical_json(a),'UTF8')),'hex')and q->>'claimCommit'~'^[a-f0-9]{40}$'and q->>'claimJsonSha256'~'^[a-f0-9]{64}$','future history-keyed consumed claim');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(b->'consumptionBinding',array['artifactId','artifactDigest','manifestSha256','runId','runAttempt','jobId','claimRef','claimCommit','claimJsonSha256'])and((b->'consumptionBinding')-array['artifactId','artifactDigest','manifestSha256','runId','runAttempt','jobId'])=q,'same consumed claim fields');
 perform private_fcf_six_target_release.require((select count(distinct x->>'artifactId')from jsonb_array_elements(jsonb_build_array(b->'consumptionBinding',b->'inventoryBinding',b->'auditBinding',b->'finalReceiptBinding'))x)=4,'distinct actual consumption/inventory/audit/final artifacts');
 for q in select b->'consumptionBinding' union all select b->'inventoryBinding' union all select b->'auditBinding' union all select b->'finalReceiptBinding'loop
  perform private_fcf_six_target_release.require(q->>'artifactId'~'^[1-9][0-9]*$'and q->>'artifactDigest'~'^sha256:[a-f0-9]{64}$'and q->>'manifestSha256'~'^[a-f0-9]{64}$'and q->>'runId'~'^[1-9][0-9]*$'and q->>'runId'=b#>>'{consumptionBinding,runId}'and q->>'runAttempt'='1'and q->>'jobId'~'^[1-9][0-9]*$','complete same-attempt artifact binding');
 end loop;
 for q in select b->'inventoryBinding' union all select b->'auditBinding' union all select b->'finalReceiptBinding'loop
  perform private_fcf_six_target_release.require(private_fcf_future_import.keys(q,array['artifactId','artifactDigest','runId','runAttempt','jobId','retentionCommit','manifestSha256'])and q->>'retentionCommit'=b->>'sourceCommit','exact retained source execution artifact');
 end loop;
end$$;


create function private_fcf_g1_supplement.validate(v jsonb,p jsonb)returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s jsonb:=v->'supplementalBinding';policy jsonb:=private_fcf_g1_supplement.policy();f jsonb;e record;expected jsonb;o jsonb;begin
 select *into e from pg_temp._fcf_expected where id='es4109409';f:=e.f;o:=f#>'{source,supplementalObservation}';
 expected:=jsonb_build_object('schemaVersion',1,'kind','fcf-g1-native-supplement','policyId',policy->>'id','policySha256','a9141400858c80322b6cb12b13c54a5dde45e93f080b4fe0b644dce513657ee7','approvalReference',policy->>'approvalReference','approvedOriginalSha256',policy->>'approvedOriginalSha256','fixture',policy->'fixture','native',jsonb_build_object('matchId',e.mid,'roundId',e.rid,'homeTeamId',e.home,'awayTeamId',e.away),'sourceCommit',v#>>'{inventoryBinding,sourceCommit}','sourceFingerprintSha256',v#>>'{inventoryBinding,sourceFingerprintSha256}');
 perform private_fcf_six_target_release.require(s=expected and p->'supplementalBinding'=expected and v->>'targetSlug'='es-ct-segona-g1'and v->>'sourceCommit'=s->>'sourceCommit'and f->>'statisticsStatus'='unavailable_historical'and f->>'statisticsReason'=policy->>'reasonCode'and f->>'policyId'=policy->>'id'and f->>'policySha256'=s->>'policySha256'and f->'homeGoals'='null'::jsonb and f->'awayGoals'='null'::jsonb and f->'report'='null'::jsonb and f->'appearances'='null'::jsonb and f->'goals'='null'::jsonb and f->'sourceFixture'=policy->'fixture'and f->>'date'='2026-10-04'and e.rn=3 and f#>>'{source,sourceUrl}'=policy#>>'{fixture,sourceUrl}'and f#>>'{clubs,0,sourceClubId}'='21434932'and f#>>'{clubs,0,sourceCategoryId}'='21442320'and f#>>'{clubs,1,sourceClubId}'='5002'and f#>>'{clubs,1,sourceCategoryId}'='37524','closed exact supplement packet/canonical/native binding');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(o,array['kind','targetSlug','sourceMatchId','policyId','policySha256','approvalReference','approvedOriginalSha256','freshRawSha256','fixture','header'])and o->>'kind'='fcf-g1-supplemental-observation'and o->>'targetSlug'='es-ct-segona-g1'and o->>'sourceMatchId'='4109409'and o->>'policyId'=policy->>'id'and o->>'policySha256'=s->>'policySha256'and o->>'approvalReference'=s->>'approvalReference'and o->>'approvedOriginalSha256'=s->>'approvedOriginalSha256'and o->>'freshRawSha256'=f#>>'{source,rawSha256}'and o->'fixture'=policy->'fixture'and o->'header'=jsonb_build_object('id','4109409','targetSlug','es-ct-segona-g1','round',3,'playedOn','2026-10-04','kickoff','17:00','status','published-result-unavailable','homeGoals',null,'awayGoals',null,'home',jsonb_build_object('sourceClubId','21434932','sourceCategoryId','21442320','name',policy->>'homeName','href','/ca/clubs/21434932/categories/21442320'),'away',jsonb_build_object('sourceClubId','5002','sourceCategoryId','37524','name',policy->>'awayName','href','/ca/clubs/5002/categories/37524')),'exact separate fresh supplemental observation');
 perform private_fcf_six_target_release.require(exists(select 1 from matches m join rounds r on r.id=m.round_id where m.id=e.mid and m.zapisnik_id='es4109409'and m.round_id=e.rid and m.home_team_id=e.home and m.away_team_id=e.away and m.played_on='2026-10-04'and r.competition_id=783 and r.season='2026/27'and r.number=3),'persisted actual report/round/side mapping; HOLD if unavailable');
 if exists(select 1 from private_fcf_g1_supplement.markers)then perform private_fcf_g1_supplement.readback(s);end if;
end$$;
create function private_fcf_g1_supplement.readback(s jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare m public.matches%rowtype;r private_fcf_g1_supplement.receipts%rowtype;marker private_fcf_g1_supplement.markers%rowtype;begin
 select *into marker from private_fcf_g1_supplement.markers;select *into m from matches where id=marker.match_id;select *into r from private_fcf_g1_supplement.receipts where match_id=marker.match_id;
 perform private_fcf_six_target_release.require(marker.binding=s and marker.before_sha256=encode(sha256(convert_to(marker.before_image_text,'UTF8')),'hex')and private_fcf_g1_supplement.exact_match(m)is true and r.after_image=to_jsonb(m)and r.receipt=jsonb_build_object('schemaVersion',1,'kind','fcf-g1-supplement-installed','sourceCommit',s->>'sourceCommit','sourceFingerprintSha256',s->>'sourceFingerprintSha256','policySha256',s->>'policySha256','beforeSha256',marker.before_sha256,'afterSha256',encode(sha256(convert_to(r.after_image::text,'UTF8')),'hex'))and not exists(select 1 from appearances where match_id=m.id)and not exists(select 1 from goals where match_id=m.id),'immutable supplemental marker/receipt/native NULL/zero individual readback');
end$$;
create function private_fcf_g1_supplement.install(v jsonb)returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s jsonb:=v->'supplementalBinding';m public.matches%rowtype;before_text text;before_sha text;after_image jsonb;projection jsonb;protected_six jsonb;begin
 if exists(select 1 from private_fcf_g1_supplement.markers)then perform private_fcf_g1_supplement.readback(s);return;end if;
 -- Caller already holds lock_target and the complete dependency locks. Recheck
 -- actual persisted native IDs; this path never resolves a title/name to an ID.
 select *into m from matches where id=(s#>>'{native,matchId}')::bigint for update;
 perform private_fcf_six_target_release.require(m.id is not null and m.zapisnik_id='es4109409'and m.round_id=(s#>>'{native,roundId}')::bigint and m.home_team_id=(s#>>'{native,homeTeamId}')::bigint and m.away_team_id=(s#>>'{native,awayTeamId}')::bigint and m.played_on='2026-10-04'and m.imported_at is null and m.statistics_status='available'and not m.kontumacija and not m.vir_brez_izida and cardinality(m.import_warnings)=0 and m.source_phase is null and(m.source_round is null or m.source_round=3)and not exists(select 1 from appearances where match_id=m.id)and not exists(select 1 from goals where match_id=m.id),'exact empty unimported native supplement; populated/guessed/dependent state HOLD');
 perform private_fcf_six_target_release.no_target_users(783);
 projection:=private_fcf_future_projection.capture('es-ct-segona-g1',array[]::text[]);
 perform private_fcf_six_target_release.require(projection#>>'{native,dependencies,complete}'='true'and projection#>>'{native,dependencies,competitionUserRows}'='0'and exists(select 1 from jsonb_array_elements(projection#>'{native,dependencies,matches}')d where(d->>'matchId')::bigint=m.id and d->>'appearances'='0'and d->>'goals'='0'and d->>'userRows'='0'),'complete locked zero individual/card/user supplement dependencies');
 select jsonb_build_object('cleanup',(select to_jsonb(c)from private_fcf_future_history.cleanup_receipt c where singleton),'six',(select jsonb_agg(public.get_installed_historical_statistics_markers(id)order by id)from competitions where id in(783,790,797)))into protected_six;
 before_text:=jsonb_build_object('match',to_jsonb(m),'appearances','[]'::jsonb,'goals','[]'::jsonb,'dependencySnapshotText',projection->>'dependencySnapshotText','dependencySnapshotSha256',projection->>'dependencySnapshotSha256')::text;before_sha:=encode(sha256(convert_to(before_text,'UTF8')),'hex');
 insert into private_fcf_g1_supplement.markers(match_id,round_id,home_team_id,away_team_id,binding,before_image_text,before_sha256,authorized_xid)values(m.id,m.round_id,m.home_team_id,m.away_team_id,s,before_text,before_sha,txid_current());
 update matches set home_goals=null,away_goals=null,imported_at=null,statistics_status='unavailable_historical',statistics_reason='closed_official_result_and_individual_statistics_unavailable',source_url='https://www.fcf.cat/ca/competicio/acta/4109409',source_phase=null,source_round=3 where id=m.id;
 select to_jsonb(mm)into after_image from matches mm where id=m.id;
 insert into private_fcf_g1_supplement.receipts values(m.id,after_image,jsonb_build_object('schemaVersion',1,'kind','fcf-g1-supplement-installed','sourceCommit',s->>'sourceCommit','sourceFingerprintSha256',s->>'sourceFingerprintSha256','policySha256',s->>'policySha256','beforeSha256',before_sha,'afterSha256',encode(sha256(convert_to(after_image::text,'UTF8')),'hex')));
 perform private_fcf_g1_supplement.readback(s);
 perform private_fcf_six_target_release.require(protected_six=jsonb_build_object('cleanup',(select to_jsonb(c)from private_fcf_future_history.cleanup_receipt c where singleton),'six',(select jsonb_agg(public.get_installed_historical_statistics_markers(id)order by id)from competitions where id in(783,790,797))),'original six immutable markers/cleanup unchanged by supplemental install');
end$$;


create or replace function private_fcf_future_import.validate(p_text text,p_sha text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare supplemental boolean;v jsonb;p jsonb;g jsonb;b jsonb;c competitions%rowtype;mp jsonb;policy private_historical_statistics.policies%rowtype;marker jsonb;due timestamptz;cb jsonb;q jsonb;stored private_fcf_future_history.cleanup_receipt%rowtype;expected_hashes jsonb;
begin
 perform private_fcf_six_target_release.require(p_sha~'^[a-f0-9]{64}$'and octet_length(p_text)<=8388608 and encode(sha256(convert_to(p_text,'UTF8')),'hex')=p_sha,'exact bounded rollout TEXT/SHA');v:=p_text::jsonb;supplemental:=coalesce(v#>>'{inventoryBinding,protocol}'='future-g1-after-failed-g1-v1',false);
 perform private_fcf_six_target_release.require(v->>'schemaVersion'=case when supplemental then '4'else '3'end and v->>'kind'='fcf-future-current-target-import-rollout'and v->>'targetSlug'in('es-ct-segona-g1','es-ct-tercera-g9')and v->>'sourceCommit'~'^[a-f0-9]{40}$'and v->'readiness'='null'::jsonb and private_fcf_future_import.keys(v,array['cleanupBinding','execution','identityPlan','inventoryBinding','kind','readiness','schemaVersion','sourceCommit','targetPacketSha256','targetPacketText','targetSlug']||case when supplemental then array['supplementalBinding']else array[]::text[]end),'closed future import rollout/null readiness');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(v->'execution',array['repository','ref','commit','runId','runAttempt'])and v#>>'{execution,repository}'='Lovro-splichal-orhanizagi/mnzgorenjska'and v#>>'{execution,ref}'='refs/heads/main'and v#>>'{execution,commit}'=v->>'sourceCommit'and v#>>'{execution,runId}'~'^[1-9][0-9]*$'and v#>>'{execution,runAttempt}'='1','reviewed main writer attempt1 tuple');
 select *into c from competitions where id=private_fcf_future_target_release.target(v->>'targetSlug');
 perform private_fcf_six_target_release.require(c.id in(783,797) and not c.active and c.prvi_fantasy_krog=1 and c.source='fcf'and c.source_policy='es-fcf-six-reviewed-history-v1'and c.source_league_code=case c.id when 783 then '4109388-4109627'else '4118349-4118588'end and not c.sezona_koledarska and c.rok_pomak_ur=6 and c.date_only_deadline_policy is null and exists(select 1 from countries where id=c.country_id and code='ES'),'exact current source/policy/calendar tuple');
 perform private_fcf_six_target_release.require(encode(sha256(convert_to(v->>'targetPacketText','UTF8')),'hex')=v->>'targetPacketSha256','nested packet TEXT/SHA');p:=(v->>'targetPacketText')::jsonb;g:=p->'target';b:=g->'sourceEvidence';
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(p,array['schemaVersion','kind','targetSlug','sourceCommit','auditedUTC','cleanupBinding','databaseInventory','target']||case when supplemental then array['supplementalBinding']else array[]::text[]end)and p->>'schemaVersion'=case when supplemental then '5'else '4'end and p->>'kind'='fcf-future-current-target-import'and p->>'targetSlug'=c.slug and p->>'sourceCommit'=v->>'sourceCommit'and(p->>'auditedUTC')::timestamptz between clock_timestamp()-interval'24 hours'and clock_timestamp()and private_fcf_future_import.keys(g,array['sourceEvidence','competitionId','competitionSlug','sourceCode','season','historicalCutline','policyId','policySha256','clubs','verifiedKeeperClubs','fixtures'])and(g->>'competitionId')::bigint=c.id and g->>'competitionSlug'=c.slug and g->>'sourceCode'=c.source_league_code and g->>'season'='2026/27'and g->>'historicalCutline'='2026-10-24'and b=v->'inventoryBinding','closed future packet/current audit/scope/cutline');
 perform private_fcf_future_import.source_binding(b);
 perform private_fcf_six_target_release.require(b->>'targetSlug'=c.slug and b->>'protocol'=case when supplemental then 'future-g1-after-failed-g1-v1'when c.id=783 then 'future-g1-after-g9-v1'else 'future-g9-after-six-v1'end,'source/packet/native selected target equality');
 if c.id=783 then perform private_fcf_future_target_release.quiet_g9();end if;
 cb:=v->'cleanupBinding';select *into stored from private_fcf_future_history.cleanup_receipt where singleton;
 select jsonb_object_agg(id,policy_sha256)into expected_hashes from private_historical_statistics.policies where document->>'sourcePolicy'='es-fcf-six-reviewed-history-v1';
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(cb,array['phase','sourceCommit','preparedUTC','beforeImageText','beforeSha256','policyHashes','originals','prepareArtifact','appliedReceipt'])and p->'cleanupBinding'=cb and cb->>'phase'='applied'and stored.singleton and not stored.restored and stored.result->>'schemaVersion'='3'and stored.result->>'removedAppearances'='157'and stored.result->>'removedGoals'='18'and stored.result->>'unavailableMatches'='6'and cb->>'sourceCommit'=stored.main_commit and cb->>'beforeImageText'=stored.before_image_text and cb->>'beforeSha256'=stored.before_sha256 and encode(sha256(convert_to(cb->>'beforeImageText','UTF8')),'hex')=stored.before_sha256 and cb->'policyHashes'=stored.policy_hashes and stored.policy_hashes=expected_hashes and cb#>'{appliedReceipt,result}'=stored.result and(cb->>'preparedUTC')::timestamptz<=clock_timestamp(),'exact stored APPLIED schema3 cleanup receipt/backup');
 perform private_fcf_future_import.markers();
 if c.id=783 then perform private_fcf_six_target_release.require(cb->>'sourceCommit'=case when supplemental then b->>'cleanupIssuerSourceCommit'else b#>>'{accountingBinding,latest,sourceCommit}'end,'G1 reuses APPLIED cleanup issued by authenticated predecessor main');end if;
 perform private_fcf_six_target_release.require(jsonb_array_length(cb->'originals')=6 and(select count(distinct x->>'sourceMatchId')from jsonb_array_elements(cb->'originals')x)=6,'all six original descriptors');
 for q in select value from jsonb_array_elements(cb->'originals')loop
  select *into policy from private_historical_statistics.policies where id=q->>'policyId';
  select value into marker from jsonb_array_elements(policy.document->'entries')where value->>'sourceMatchId'=q->>'sourceMatchId';
  perform private_fcf_six_target_release.require(marker is not null and policy.policy_sha256=q->>'policySha256'and q->>'competitionSlug'=policy.document->>'competitionSlug'and policy.document->>'sourcePolicy'='es-fcf-six-reviewed-history-v1'and q#>>'{receipt,rawSha256}'=marker->>'rawSha256'and q->'fixture'=(marker-array['rawSha256','reasonCode'])||jsonb_build_object('season','2026/27'),'immutable original descriptor/hash/fixture');
 end loop;
 select *into policy from private_historical_statistics.policies where id=g->>'policyId';
 perform private_fcf_six_target_release.require(policy.id=c.slug||'-six-reviewed-2026-10-19-v1'and policy.document->>'competitionSlug'=c.slug and policy.policy_sha256=g->>'policySha256','exact installed G9 policy');
 mp:=(v#>>'{identityPlan,mappingText}')::jsonb;
 perform private_fcf_six_target_release.require(encode(sha256(convert_to(v#>>'{identityPlan,mappingText}','UTF8')),'hex')=v#>>'{identityPlan,mappingSha256}'and private_fcf_future_import.keys(v->'identityPlan',array['mappingText','mappingSha256'])and private_fcf_future_import.keys(mp,array['schemaVersion','kind','targetSlug','sourceCommit','captureSourceCommit','auditedUTC','sourceFingerprintSha256','databaseSha256','existingExceptionBindingsSha256','mappings','fixtures'])and mp->>'schemaVersion'='1'and mp->>'captureSourceCommit'=b->>'sourceCommit'and(mp->>'auditedUTC')::timestamptz between clock_timestamp()-interval'24 hours'and clock_timestamp()and mp->>'databaseSha256'~'^[a-f0-9]{64}$'and mp->>'existingExceptionBindingsSha256'~'^[a-f0-9]{64}$'and mp->>'kind'='fcf-native-target-mapping'and mp->>'targetSlug'=c.slug and mp->>'sourceCommit'=v->>'sourceCommit'and mp->>'sourceFingerprintSha256'=b->>'sourceFingerprintSha256'and jsonb_array_length(mp->'mappings')=16 and jsonb_array_length(mp->'fixtures')=240,'reviewed native mapping text/identity required');
 drop table if exists pg_temp._fcf_clubs;create temporary table pg_temp._fcf_clubs on commit drop as select x->>'nativeClubId'club,x->>'nativeCategoryId'category,(x->>'teamId')::bigint team,x->>'sourceName'name,x->>'canonicalTeamName'canonical_name from jsonb_array_elements(mp->'mappings')x;
 perform private_fcf_six_target_release.require((select count(distinct(club,category))from pg_temp._fcf_clubs)=16 and(select count(distinct team)from pg_temp._fcf_clubs)=16 and not exists(select 1 from pg_temp._fcf_clubs n left join teams t on t.id=n.team where t.id is null or t.country_id<>c.country_id or t.name is distinct from n.canonical_name or n.club!~'^[1-9][0-9]*$'or n.category!~'^[1-9][0-9]*$'),'native club/team/country bijection required');
 drop table if exists pg_temp._fcf_expected;create temporary table pg_temp._fcf_expected(id text primary key,f jsonb,mid bigint unique,rid bigint,rn int,home bigint,away bigint)on commit drop;
 insert into pg_temp._fcf_expected select f->>'id',f,(x->>'matchId')::bigint,(x->>'roundId')::bigint,(f->>'round')::int,h.team,a.team from jsonb_array_elements(g->'fixtures')f join lateral(select value x from jsonb_array_elements(mp->'fixtures')where value->>'sourceMatchId'=f->>'id')map on true join pg_temp._fcf_clubs h on h.club=f#>>'{clubs,0,sourceClubId}'and h.category=f#>>'{clubs,0,sourceCategoryId}'join pg_temp._fcf_clubs a on a.club=f#>>'{clubs,1,sourceClubId}'and a.category=f#>>'{clubs,1,sourceCategoryId}';
 perform private_fcf_six_target_release.require((select count(*)from pg_temp._fcf_expected)=240 and(select count(*)from rounds where competition_id=c.id)=30 and(select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=c.id)=240 and(select count(distinct(home,away))from pg_temp._fcf_expected)=240 and not exists(select 1 from pg_temp._fcf_expected e left join matches m on m.id=e.mid left join rounds r on r.id=e.rid where m.id is null or m.round_id<>e.rid or r.competition_id<>c.id or r.season<>'2026/27'or r.number<>e.rn or e.home=e.away or m.home_team_id<>e.home or m.away_team_id<>e.away or(m.zapisnik_id is not null and m.zapisnik_id<>e.id)or(m.imported_at is not null and e.f->>'statisticsStatus'='pending')or e.id!~'^es[1-9][0-9]*$'or substring(e.id from 3)::bigint not between(case c.id when 783 then 4109388 else 4118349 end)and(case c.id when 783 then 4109627 else 4118588 end)),'complete actual native240/30/calendar/import preservation required');
 perform private_fcf_six_target_release.require(not exists(select n from generate_series(1,30)n left join pg_temp._fcf_expected e on e.rn=n group by n having count(e.id)<>8 or count(distinct e.home)filter(where e.home is not null)>8 or count(distinct e.away)filter(where e.away is not null)>8)and not exists(select rn from(select rn,home team from pg_temp._fcf_expected union all select rn,away from pg_temp._fcf_expected)x group by rn having count(distinct team)<>16),'every club once per actual source round');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where e.f->>'statisticsStatus'not in('available','pending','unavailable_historical')or e.f->>'statisticsStatus'is null or (e.f#>>'{source,capturedUTC}'is null or(e.f#>>'{source,capturedUTC}')::timestamptz>clock_timestamp()or(e.f#>>'{source,capturedUTC}')::timestamptz<clock_timestamp()-interval '24 hours')),'strict current source clocks/status required');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where e.f->>'statisticsStatus'='pending'and clock_timestamp()-((e.f->>'date')::date::timestamp at time zone'UTC')between interval'-1 day'and interval'14 days'and(e.f#>>'{source,capturedUTC}')::timestamptz<clock_timestamp()-interval'1 hour'),'pending source provider one-hour freshness required');
 perform private_fcf_six_target_release.require((select array_agg(substring(id from 3)order by id)from pg_temp._fcf_expected where f->>'statisticsStatus'='unavailable_historical')=(select array_agg(id order by id)from(select x->>'sourceMatchId'id from jsonb_array_elements(policy.document->'entries')x union all select '4109409'where supplemental)u),'exact target historical exceptions only');
 for marker in select value from jsonb_array_elements(policy.document->'entries')loop
  perform private_fcf_six_target_release.require(exists(select 1 from pg_temp._fcf_expected where id='es'||(marker->>'sourceMatchId')and f->'appearances'='null'::jsonb and f->'goals'='null'::jsonb and f#>>'{source,rawSha256}'~'^[a-f0-9]{64}$'and f#>'{source,historicalObservation}'=jsonb_build_object('kind','fcf-six-fresh-historical-observation','targetSlug',c.slug,'sourceMatchId',marker->>'sourceMatchId','policyId',policy.id,'policySha256',policy.policy_sha256,'approvedOriginalSha256',marker->>'rawSha256','freshRawSha256',f#>>'{source,rawSha256}','fixture',(marker-array['rawSha256','reasonCode'])||jsonb_build_object('season','2026/27'))and f->'report'='null'::jsonb and f->>'policyId'=policy.id and f->>'policySha256'=policy.policy_sha256 and f->>'date'=marker->>'playedOn'and(f->>'round')::int=(marker->>'sourceRound')::int and f->'homeGoals'=marker->'observedHomeScore'and f->'awayGoals'=marker->'observedAwayScore'and f->>'statisticsReason'=marker->>'reasonCode'and f->'sourceFixture'=(marker-array['rawSha256','reasonCode'])||jsonb_build_object('season','2026/27')),'immutable unavailable header/hash/null facts required');
 end loop;
 drop table if exists pg_temp._fcf_apps;create temporary table pg_temp._fcf_apps on commit drop as select e.id,e.mid,e.rid,e.rn,e.f->>'date' as source_day,(x->>'regSt')::bigint reg,case x->>'ekipaIdx'when '0'then e.home when '1'then e.away end team,x from pg_temp._fcf_expected e cross join lateral jsonb_array_elements(case when f->>'statisticsStatus'='available'then f->'appearances'else '[]'::jsonb end)x;
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_apps where reg is null or reg<1 or team is null or x->>'ime'is null or jsonb_typeof(x->'zacetnik')is distinct from'boolean'or jsonb_typeof(x->'vratar')is distinct from'boolean'or jsonb_typeof(x->'cleanSheet')is distinct from'boolean'or exists(select 1 from unnest(array['goli','avtogoli','goliIzEnajstmetrovke','zgreseneEnajstmetrovke','rumeni','rdeci','prejetiGoli'])field where jsonb_typeof(x->field)is distinct from'number'or(x->>field)::int<0)or(x->>'minute')::int<0 or(x->>'minutaOd')::int<0 or(x->>'minutaDo')::int>90 or(x->>'minute')::int<>(x->>'minutaDo')::int-(x->>'minutaOd')::int)and not exists(select id,reg from pg_temp._fcf_apps group by id,reg having count(*)<>1),'native appearance identity/intervals');
 perform private_fcf_six_target_release.require(not exists(select id,team from pg_temp._fcf_apps group by id,team having count(*)filter(where(x->>'zacetnik')::boolean)<>11 or count(*)filter(where(x->>'zacetnik')::boolean and(x->>'vratar')::boolean)<>1)and not exists(select 1 from(select id,team,(x->>'minutaOd')::int a,(x->>'minutaDo')::int b,lag((x->>'minutaDo')::int,1,0)over(partition by id,team order by(x->>'minutaOd')::int,(x->>'minutaDo')::int)previous from pg_temp._fcf_apps where(x->>'vratar')::boolean and(x->>'minute')::int>0)k where a<>previous)and not exists(select id,team from pg_temp._fcf_apps where(x->>'vratar')::boolean and(x->>'minute')::int>0 group by id,team having max((x->>'minutaDo')::int)<>90),'explicit XI and continuous exactly-one source GK0-90');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where f->>'statisticsStatus'='available'and(coalesce(f#>'{report,opozorila}','null')<>'[]'::jsonb or(select count(*)from pg_temp._fcf_apps a where a.id=e.id)<22)),'normal complete current reports only; no source-role repair');
 drop table if exists pg_temp._fcf_goals;create temporary table pg_temp._fcf_goals on commit drop as select e.id,e.mid,(ge.goal->>'regSt')::bigint reg,case ge.goal->>'ekipaIdx'when '0'then e.home when '1'then e.away end team,ge.goal as g from pg_temp._fcf_expected e cross join lateral jsonb_array_elements(case when f->>'statisticsStatus'='available'then f->'goals'else '[]'::jsonb end)ge(goal);
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_goals g where g.reg is null or not exists(select 1 from pg_temp._fcf_apps a where a.id=g.id and a.reg=g.reg and a.team=g.team and(g.g->>'minuta')::int between(a.x->>'minutaOd')::int and(a.x->>'minutaDo')::int))and not exists(select 1 from pg_temp._fcf_expected e where f->>'statisticsStatus'='available'and((select count(*)from pg_temp._fcf_goals g where g.id=e.id and case when(g.g->>'avtogol')::boolean then g.team=e.away else g.team=e.home end)<>(f->>'homeGoals')::int or(select count(*)from pg_temp._fcf_goals g where g.id=e.id and case when(g.g->>'avtogol')::boolean then g.team=e.home else g.team=e.away end)<>(f->>'awayGoals')::int)),'native goal actors/score accounting');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_apps a where(a.x->>'goli')::int<>(select count(*)from pg_temp._fcf_goals ge where ge.id=a.id and ge.reg=a.reg and not(ge.g->>'avtogol')::boolean)or(a.x->>'avtogoli')::int<>(select count(*)from pg_temp._fcf_goals ge where ge.id=a.id and ge.reg=a.reg and(ge.g->>'avtogol')::boolean)or(a.x->>'goliIzEnajstmetrovke')::int<>(select count(*)from pg_temp._fcf_goals ge where ge.id=a.id and ge.reg=a.reg and(ge.g->>'enajstmetrovka')::boolean and not(ge.g->>'avtogol')::boolean)),'native per-player goal event counters differ');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected where f#>>'{source,sourceUrl}'is distinct from 'https://www.fcf.cat/ca/competicio/acta/'||substring(id from 3)or f#>>'{source,rawSha256}'is null or f#>>'{source,rawSha256}'!~'^[a-f0-9]{64}$'),'exact source URLs/raw hashes');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_clubs n where not exists(select 1 from pg_temp._fcf_apps a where a.team=n.team and(a.x->>'vratar')::boolean and(a.x->>'zacetnik')::boolean)),'all16 clubs explicit official goalkeeper evidence');
 -- Bind every policy observation back to its typed official fixture and current
 -- capture, while preserving the immutable original authorization SHA separately.
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where e.f->>'date'is null or e.f->>'date'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or e.f#>>'{source,rawSha256}'is null or e.f#>>'{source,rawSha256}'!~'^[a-f0-9]{64}$'or jsonb_array_length(e.f->'clubs')<>2 or exists(select 1 from jsonb_array_elements(e.f->'clubs')cl left join pg_temp._fcf_clubs n on n.club=cl->>'sourceClubId'and n.category=cl->>'sourceCategoryId'where n.team is null or n.name is distinct from cl->>'name')),'complete official fixture dates/clubs/current source bytes');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_clubs n join private_historical_statistics.source_club_bindings sb on sb.provider='fcf'and sb.source_club_id=n.club and sb.source_category_id=n.category where sb.country_code<>'ES'or sb.bound_team_id is distinct from n.team),'installed historical club/category anchors');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e cross join lateral jsonb_array_elements(policy.document->'entries')entry where e.id='es'||(entry->>'sourceMatchId')and(e.f#>>'{clubs,0,sourceClubId}'is distinct from entry->>'homeSourceClubId'or e.f#>>'{clubs,0,sourceCategoryId}'is distinct from entry->>'homeSourceCategoryId'or e.f#>>'{clubs,1,sourceClubId}'is distinct from entry->>'awaySourceClubId'or e.f#>>'{clubs,1,sourceCategoryId}'is distinct from entry->>'awaySourceCategoryId')),'exact historical official club/category sides');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e cross join lateral(values(e.home),(e.away))side(team)where e.f->>'statisticsStatus'='available'and(select count(*)from pg_temp._fcf_apps a where a.id=e.id and a.team=side.team and(a.x->>'zacetnik')::boolean)<>11),'explicit eleven starters for BOTH official sides');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_apps a where a.x->>'ime'=''or exists(select 1 from unnest(array['regSt','st','ekipaIdx','minutaOd','minutaDo','minute'])field where jsonb_typeof(a.x->field)is distinct from'number')or(a.x->>'minutaDo')::int<0 or(a.x->>'minutaOd')::int>90 or(a.x->>'minutaOd')::int>(a.x->>'minutaDo')::int or(a.x->>'st')::int<1),'complete numeric source actor intervals');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_goals ge where jsonb_typeof(ge.g->'avtogol')is distinct from'boolean'or jsonb_typeof(ge.g->'enajstmetrovka')is distinct from'boolean'or jsonb_typeof(ge.g->'minuta')is distinct from'number'or(ge.g->>'minuta')::int not between 0 and 90 or case
   when jsonb_typeof(ge.g->'rezultat')is distinct from'array'then true
   when jsonb_array_length(ge.g->'rezultat')<>2 then true
   else exists(select 1 from jsonb_array_elements(ge.g->'rezultat')score where case
    when jsonb_typeof(score)is distinct from'number'then true
    else score::text!~'^(0|[1-9][0-9]*)$'or score::text::numeric>2147483647
   end)
  end),'complete goal event flags/clock/score');
 perform private_fcf_six_target_release.require(jsonb_array_length(g->'clubs')=16 and jsonb_array_length(g->'verifiedKeeperClubs')=16 and not exists(with actual as(select jsonb_build_object('sourceClubId',club,'sourceCategoryId',category,'name',name)j from pg_temp._fcf_clubs),expected as(select value j from jsonb_array_elements(g->'clubs'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual))and not exists(with actual as(select club||'/'||category j from pg_temp._fcf_clubs),expected as(select value j from jsonb_array_elements_text(g->'verifiedKeeperClubs'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual)),'complete actual16 official club and keeper sets');
 if supplemental then perform private_fcf_g1_supplement.validate(v,p);end if;
 return v;
end$$;


create or replace function public.fcf_future_current_target_import(p_rollout_text text,p_sha256 text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_column
declare v jsonb;cid bigint;c competitions%rowtype;rec private_fcf_future_target_release.receipts%rowtype;k text;f record;x record;current_player players%rowtype;pid bigint;apps jsonb;gs jsonb;due timestamptz;rid bigint;result jsonb;projection jsonb;privacy_keys text[];protected jsonb;q record;other_image jsonb;
begin
 cid:=private_fcf_future_target_release.target(p_rollout_text::jsonb->>'targetSlug');perform set_config('lock_timeout','10s',true);perform private_fcf_six_target_release.lock_target(cid);perform private_fcf_future_import.lock_dependencies();if cid=783 then perform private_fcf_future_target_release.quiet_g9();other_image:=private_fcf_future_target_release.g9_image();end if;v:=private_fcf_future_import.validate(p_rollout_text,p_sha256);select *into c from competitions where id=cid;
 k:=encode(sha256(convert_to((v->'inventoryBinding')::text,'UTF8')),'hex');select *into rec from private_fcf_future_target_release.receipts where competition_id=cid and inventory_key=k;
 select coalesce(array_agg(distinct s.k order by s.k),'{}')into privacy_keys from(select public.anonimizacijski_kljuc(c.country_id||'|reg|'||a.reg)k from pg_temp._fcf_apps a union select public.anonimizacijski_kljuc(c.country_id||'|'||(a.x->>'ime'))from pg_temp._fcf_apps a)s;
 perform private_fcf_six_target_release.no_target_users(cid);perform private_fcf_six_target_release.privacy(cid);
 if v#>>'{inventoryBinding,protocol}'='future-g1-after-failed-g1-v1'then perform private_fcf_g1_supplement.install(v);end if;
 projection:=private_fcf_future_projection.capture(c.slug,privacy_keys);
 perform private_fcf_six_target_release.require(projection#>>'{native,dependencies,complete}'='true'and projection#>>'{native,dependencies,competitionUserRows}'='0','complete locked native dependency/user projection');
 if rec.id is not null then
  perform private_fcf_six_target_release.require((select count(*)from private_fcf_six_target_release.club_bindings where competition_id=cid)=16 and not exists(select 1 from pg_temp._fcf_clubs n left join private_fcf_six_target_release.club_bindings sb on sb.competition_id=cid and sb.club_id=n.club and sb.category_id=n.category and sb.team_id=n.team and sb.country_id=c.country_id and sb.source_fingerprint=v#>>'{inventoryBinding,sourceFingerprintSha256}'where sb.team_id is null),'stored actual native club bindings drift');
  perform private_fcf_six_target_release.require(rec.stage='imported'and rec.rollout_text=p_rollout_text and rec.rollout_sha256=p_sha256 and rec.packet_text=v->>'targetPacketText'and rec.packet_sha256=v->>'targetPacketSha256'and rec.source_fingerprint=v#>>'{inventoryBinding,sourceFingerprintSha256}'and rec.cleanup_before_sha256=v#>>'{cleanupBinding,beforeSha256}'and rec.imported_state_sha256=private_historical_statistics.state_sha256(cid),'exact same saved payload/state required; no blind retry');
  perform private_fcf_six_target_release.compare_canonical(cid);
  if cid=783 then perform private_fcf_six_target_release.require(private_fcf_future_target_release.g9_image()=other_image,'G1 import preserves exact G9 afterimage/receipt');end if;
 return jsonb_build_object('stage','imported','targetSlug',c.slug,'receiptId',rec.id::text,'noOp',true,'targetPacketSha256',rec.packet_sha256);
 end if;
 perform private_fcf_six_target_release.require(not exists(select 1 from private_fcf_future_target_release.receipts where competition_id=cid)and not exists(select 1 from private_fcf_six_target_release.receipts where competition_id=cid)and not exists(select 1 from private_fcf_target_release.receipts where competition_id=cid),'single new inactive future import only');
 select jsonb_build_object('competition',to_jsonb(c),'rounds',(select jsonb_agg(to_jsonb(r)order by id)from rounds r where competition_id=cid))into protected;
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_clubs n join private_fcf_six_target_release.club_bindings b on b.competition_id=cid and b.club_id=n.club and b.category_id=n.category where b.team_id<>n.team or b.country_id<>c.country_id or b.source_fingerprint is distinct from v#>>'{inventoryBinding,sourceFingerprintSha256}'),'immutable private native binding conflict');
 insert into private_fcf_six_target_release.club_bindings select cid,n.club,n.category,n.team,c.country_id,v#>>'{inventoryBinding,sourceFingerprintSha256}'from pg_temp._fcf_clubs n on conflict do nothing;
 for x in select distinct on(aa.reg)aa.reg,aa.team,aa.x from pg_temp._fcf_apps aa order by aa.reg,aa.source_day::date desc,aa.id desc loop
  select *into current_player from players where competition_id=cid and reg_st=x.reg;
  if current_player.id is null then
   insert into players(competition_id,team_id,reg_st,full_name,first_name,last_name,position,position_source)values(cid,x.team,x.reg,x.x->>'ime',regexp_replace(x.x->>'ime','^\S+\s*',''),split_part(x.x->>'ime',' ',1),case when exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'GK'end,case when exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'zapisnik'else 'neznano'end);
  else
   update players set team_id=x.team,shirt_number=(x.x->>'st')::int,active=case when odsel_at is null and izstopil_at is null then true else active end,position=case when position_source is distinct from 'admin'and(position is null or position_source in('neznano','ugibanje'))and exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'GK'else position end,position_source=case when position_source is distinct from 'admin'and(position is null or position_source in('neznano','ugibanje'))and exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'zapisnik'else position_source end where id=current_player.id;
  end if;
 end loop;
 update players set active=false where competition_id=cid and team_id not in(select team from pg_temp._fcf_clubs);
 for f in select *from pg_temp._fcf_expected order by id loop
  if f.f->>'statisticsStatus'='unavailable_historical'then continue;end if;
  update matches set played_on=(f.f->>'date')::date,home_goals=case when f.f->>'statisticsStatus'='pending'then 0 else(f.f->>'homeGoals')::int end,away_goals=case when f.f->>'statisticsStatus'='pending'then 0 else(f.f->>'awayGoals')::int end,zapisnik_id=f.id,source_url=f.f#>>'{source,sourceUrl}',source_round=f.rn,source_phase=null,imported_at=case when f.f->>'statisticsStatus'='available'then clock_timestamp()end,import_warnings=array[]::text[],statistics_status='available',statistics_reason=null where id=f.mid;
  select coalesce(jsonb_agg(jsonb_build_object('player_id',p.id,'team_id',a.team,'shirt_number',a.x->'st','started',a.x->'zacetnik','minute_on',a.x->'minutaOd','minute_off',a.x->'minutaDo','minutes_played',a.x->'minute','goals',a.x->'goli','own_goals',a.x->'avtogoli','penalties_scored',a.x->'goliIzEnajstmetrovke','penalties_missed',a.x->'zgreseneEnajstmetrovke','yellow_cards',a.x->'rumeni','red_cards',a.x->'rdeci','goals_conceded',a.x->'prejetiGoli','clean_sheet',a.x->'cleanSheet','is_goalkeeper',a.x->'vratar')),'[]')into apps from pg_temp._fcf_apps a join players p on p.competition_id=cid and p.reg_st=a.reg where a.id=f.id;
  select coalesce(jsonb_agg(jsonb_build_object('scorer_id',p.id,'team_id',g.team,'minute',g.g->'minuta','is_own_goal',g.g->'avtogol','is_penalty',g.g->'enajstmetrovka','score_home',g.g#>'{rezultat,0}','score_away',g.g#>'{rezultat,1}')),'[]')into gs from pg_temp._fcf_goals g join players p on p.competition_id=cid and p.reg_st=g.reg where g.id=f.id;
  perform public.zamenjaj_nastope_tekme(f.mid,apps,gs);
 end loop;
 -- Official calendar dates may refresh; no fantasy round, deadline or lock writes.
 update rounds r set played_on=d.source_day from(select rn,min((f->>'date')::date) as source_day from pg_temp._fcf_expected group by rn)d where r.competition_id=cid and r.season='2026/27'and r.number=d.rn;
 perform private_fcf_six_target_release.require((select to_jsonb(co)from competitions co where id=cid)=protected->'competition'and not exists(select 1 from rounds r join jsonb_array_elements(protected->'rounds')b on(b->>'id')::bigint=r.id where to_jsonb(r)-'played_on'<>b-'played_on'),'inactive seed1, all locks/deadlines and competition configuration preserved');
 for rid in select id from rounds where competition_id=cid loop perform public.recompute_round_scores(rid);end loop;perform public.osvezi_statistiko_igralcev(array(select id from players where competition_id=cid));
 perform private_fcf_six_target_release.compare_canonical(cid);
 insert into private_fcf_future_target_release.receipts(competition_id,inventory_key,packet_sha256,packet_text,rollout_text,rollout_sha256,source_fingerprint,cleanup_before_sha256,imported_state_sha256,stage)values(cid,k,v->>'targetPacketSha256',v->>'targetPacketText',p_rollout_text,p_sha256,v#>>'{inventoryBinding,sourceFingerprintSha256}',v#>>'{cleanupBinding,beforeSha256}',private_historical_statistics.state_sha256(cid),'imported')returning *into rec;
 if cid=783 then perform private_fcf_six_target_release.require(private_fcf_future_target_release.g9_image()=other_image,'G1 import preserves exact G9 afterimage/receipt');end if;
 return jsonb_build_object('stage','imported','targetSlug',c.slug,'receiptId',rec.id::text,'targetPacketSha256',rec.packet_sha256,'normalReports',(select count(*)from pg_temp._fcf_expected e where e.f->>'statisticsStatus'='available'),'fixtures',240,'nativeClubs',16);
end$$;


create or replace function private_fcf_future_activation.after_image(p_cid bigint)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('footballSha256',private_historical_statistics.state_sha256(p_cid),'active',(select active from competitions where id=p_cid),'pricingSnapshotText',private_fcf_six_target_release.pricing_snapshot(p_cid)::text,'installedPolicy',(select to_jsonb(i)from private_historical_statistics.installed_policies i where competition_id=p_cid),'markers',public.get_installed_historical_statistics_markers(p_cid),'clubBindings',(select jsonb_agg(to_jsonb(b)order by club_id,category_id)from private_fcf_six_target_release.club_bindings b where competition_id=p_cid),'cleanupSha256',(select encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')from private_fcf_future_history.cleanup_receipt r where singleton))||case when p_cid=783 and exists(select 1 from private_fcf_g1_supplement.markers)then jsonb_build_object('supplementalMarker',public.get_installed_fcf_g1_supplement())else '{}'::jsonb end;
$$;



create or replace function public.fcf_future_current_target_check(p_activation_text text,p_sha256 text,p_activate boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_column
declare
 cid bigint;other_image jsonb;a jsonb;v jsonb;packet jsonb;mp jsonb;c competitions%rowtype;rec private_fcf_future_target_release.receipts%rowtype;
 projection jsonb;native jsonb;proposal jsonb;readiness jsonb;privacy_keys text[];now_utc timestamptz:=clock_timestamp();
 gap int;later_count int;last_played int;selected int;rid bigint;earliest timestamptz;deadline timestamptz;opening date;
 launch_projection jsonb;expected_proposal jsonb;projection_sha text;price_text text;prices jsonb;cost numeric;result jsonb;
 protected_players jsonb;protected_policy jsonb;protected_cleanup text;expected_competition jsonb;expected_rounds jsonb;after_native jsonb;after_image jsonb;
begin
 perform set_config('lock_timeout','10s',true);
 perform private_fcf_six_target_release.require(p_activate is not null and p_sha256~'^[a-f0-9]{64}$'and octet_length(p_activation_text)<=8388608 and encode(sha256(convert_to(p_activation_text,'UTF8')),'hex')=p_sha256,'exact bounded activation TEXT/SHA');a:=p_activation_text::jsonb;
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(a,array['schemaVersion','kind','targetSlug','sourceCommit','execution','importReceiptId','importRolloutText','importRolloutSha256','nativeSnapshotText','nativeSnapshotSha256','launchProposal','readiness','auditedUTC'])and a->'schemaVersion'=case when((a->>'importRolloutText')::jsonb)#>>'{inventoryBinding,protocol}'='future-g1-after-failed-g1-v1'then '5'::jsonb else '4'::jsonb end and not exists(select 1 from unnest(array['targetSlug','sourceCommit','importReceiptId','importRolloutText','importRolloutSha256','nativeSnapshotText','nativeSnapshotSha256','auditedUTC'])field where jsonb_typeof(a->field)is distinct from'string')and a->>'kind'='fcf-future-current-target-activation'and a->>'targetSlug'in('es-ct-segona-g1','es-ct-tercera-g9')and a->>'sourceCommit'~'^[a-f0-9]{40}$'and jsonb_typeof(a->'importReceiptId')='string'and a->>'importReceiptId'~'^[1-9][0-9]*$','closed future activation schema4/G9');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(a->'execution',array['repository','ref','commit','runId','runAttempt'])and a#>>'{execution,repository}'='Lovro-splichal-orhanizagi/mnzgorenjska'and a#>>'{execution,ref}'='refs/heads/main'and a#>>'{execution,commit}'=a->>'sourceCommit'and jsonb_typeof(a#>'{execution,runId}')='string'and a#>'{execution,runAttempt}'='"1"'::jsonb and a#>>'{execution,runId}'~'^[1-9][0-9]*$'and a#>>'{execution,runAttempt}'='1','exact approved main activation attempt1');
 cid:=private_fcf_future_target_release.target(a->>'targetSlug');perform private_fcf_six_target_release.lock_target(cid);perform private_fcf_future_import.lock_dependencies();if cid=783 then perform private_fcf_future_target_release.quiet_g9();other_image:=private_fcf_future_target_release.g9_image();end if;
 select *into c from competitions where id=cid;select *into rec from private_fcf_future_target_release.receipts where competition_id=cid and id::text=a->>'importReceiptId';
 perform private_fcf_six_target_release.require(rec.id is not null and rec.rollout_text=a->>'importRolloutText'and rec.rollout_sha256=a->>'importRolloutSha256'and encode(sha256(convert_to(rec.rollout_text,'UTF8')),'hex')=rec.rollout_sha256,'exact committed original import receipt/rollout');
 v:=rec.rollout_text::jsonb;packet:=rec.packet_text::jsonb;perform private_fcf_six_target_release.require(v->>'targetSlug'=c.slug and packet->>'targetSlug'=c.slug and packet#>>'{target,competitionId}'=cid::text and v#>>'{inventoryBinding,targetSlug}'=c.slug and v#>>'{inventoryBinding,protocol}'=case when v#>>'{inventoryBinding,protocol}'='future-g1-after-failed-g1-v1'then 'future-g1-after-failed-g1-v1'when cid=783 then 'future-g1-after-g9-v1'else 'future-g9-after-six-v1'end,'activation source/packet/receipt native target equality');
 perform private_fcf_six_target_release.require(rec.inventory_key=encode(sha256(convert_to((v->'inventoryBinding')::text,'UTF8')),'hex')and v->>'targetPacketText'=rec.packet_text and v->>'targetPacketSha256'=rec.packet_sha256 and encode(sha256(convert_to(rec.packet_text,'UTF8')),'hex')=rec.packet_sha256 and rec.source_fingerprint=v#>>'{inventoryBinding,sourceFingerprintSha256}'and rec.cleanup_before_sha256=v#>>'{cleanupBinding,beforeSha256}','original import packet/source/cleanup receipt identity');
 if v#>>'{inventoryBinding,protocol}'='future-g1-after-failed-g1-v1'then perform private_fcf_six_target_release.require(a->>'sourceCommit'=v#>>'{inventoryBinding,sourceCommit}'and v->>'sourceCommit'=a->>'sourceCommit','same actual fresh source/final native writer through activation');perform private_fcf_g1_supplement.readback(v->'supplementalBinding');end if;
 -- Committed retries are exact readback only. They do not call inactive-only
 -- projection/validation helpers, reselect an opening or claim fresh readiness.
 if rec.stage='activated'then
  perform private_fcf_six_target_release.require(c.active and rec.activation_result->>'activationText'=p_activation_text and rec.activation_result->>'activationSha256'=p_sha256 and rec.activation_result->'afterImage'=private_fcf_future_activation.after_image(cid),'saved activation/current afterimage drift');
  perform private_fcf_future_import.markers();perform private_fcf_six_target_release.no_target_users(cid);
  return rec.activation_result->'result'||jsonb_build_object('noOp',true,'readbackOnly',true);
 end if;
 perform private_fcf_six_target_release.require(rec.stage='imported'and rec.activation_result is null and not c.active and c.prvi_fantasy_krog=1 and(a->>'auditedUTC')::timestamptz between now_utc-interval'24 hours'and now_utc,'inactive imported seed1/current activation audit');
 -- The saved import uses its ORIGINAL writer execution and pre-import packet;
 -- intentional post-import repricing does not need the old imported-state hash.
 v:=private_fcf_future_import.validate(rec.rollout_text,rec.rollout_sha256);
 perform private_fcf_six_target_release.no_target_users(cid);perform private_fcf_six_target_release.privacy(cid);perform private_fcf_six_target_release.compare_canonical(cid);
 select coalesce(array_agg(distinct k order by k),'{}')into privacy_keys from(select public.anonimizacijski_kljuc(c.country_id||'|reg|'||e.reg)k from pg_temp._fcf_apps e union select public.anonimizacijski_kljuc(c.country_id||'|'||(e.x->>'ime'))from pg_temp._fcf_apps e)s;
 projection:=private_fcf_future_projection.capture(c.slug,privacy_keys);native:=projection->'native';proposal:=a->'launchProposal';readiness:=a->'readiness';
 perform private_fcf_six_target_release.require(a->>'nativeSnapshotText'=projection->>'dependencySnapshotText'and a->>'nativeSnapshotSha256'=projection->>'dependencySnapshotSha256'and encode(sha256(convert_to(a->>'nativeSnapshotText','UTF8')),'hex')=a->>'nativeSnapshotSha256'and native#>>'{dependencies,complete}'='true'and native#>>'{dependencies,competitionUserRows}'='0','exact locked SQL native/dependency snapshot');
 mp:=(v#>>'{identityPlan,mappingText}')::jsonb;
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(mp->'fixtures')m where not private_fcf_future_import.keys(m,array['sourceMatchId','sourceRound','matchId','roundId','homeTeamId','awayTeamId']))and not exists(with actual as(select jsonb_build_object('sourceMatchId',id,'sourceRound',rn,'matchId',mid,'roundId',rid,'homeTeamId',home,'awayTeamId',away)j from pg_temp._fcf_expected),expected as(select value j from jsonb_array_elements(mp->'fixtures'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual)),'complete original source/native mapping identities');
 perform private_fcf_six_target_release.require(not exists(select 1 from rounds where competition_id=cid and(deadline_at is null or played_on is null or played_on<'2026-07-01'or played_on>='2027-07-01')),'complete current native round dates/deadlines');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where(e.f->>'date')::date<'2026-07-01'or(e.f->>'date')::date>='2027-07-01'),'exact current-season source dates');
 gap:=private_fcf_future_activation.next_round(cid,0,now_utc);
 select count(distinct rn)into later_count from pg_temp._fcf_expected where f->>'statisticsStatus'='available'and rn>gap;
 select coalesce(max(rn),0)into last_played from pg_temp._fcf_expected where f->>'statisticsStatus'='available'and(rn<gap or later_count>2);
 selected:=case when gap>last_played then gap else private_fcf_future_activation.next_round(cid,last_played,now_utc)end;
 select id into rid from rounds where competition_id=cid and season='2026/27'and number=selected;
 earliest:=private_fcf_future_activation.official_clock(selected);deadline:=earliest-interval'6 hours';select min((f->>'date')::date)into opening from pg_temp._fcf_expected where rn=selected;
 perform private_fcf_six_target_release.require((select count(*)from pg_temp._fcf_expected where rn=selected)=8 and not exists(select 1 from pg_temp._fcf_expected e join matches m on m.id=e.mid where e.rn=selected and(e.f->>'statisticsStatus'<>'pending'or(e.f->>'date')::date<=(now_utc at time zone'UTC')::date or m.played_on is distinct from(e.f->>'date')::date or m.imported_at is not null or m.kontumacija or m.vir_brez_izida or m.statistics_status<>'available'))and exists(select 1 from rounds where id=rid and played_on=opening and deadline_at>now_utc and lineups_locked_at is null)and deadline>clock_timestamp(),'same genuinely future untouched source/native opening');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(native#>'{dependencies,rounds}')d where(d->>'roundId')::bigint=rid and(d->>'lineupRows'<>'0'or d->>'rosterRows'<>'0'or d->>'transferRows'<>'0'or d->>'chipRows'<>'0'or d->>'userRows'<>'0'))and not exists(select 1 from jsonb_array_elements(native#>'{dependencies,matches}')d where(d->>'matchId')::bigint in(select mid from pg_temp._fcf_expected where rn=selected)and(d->>'appearances'<>'0'or d->>'goals'<>'0'or d->>'userRows'<>'0')),'zero selected native statistics/user dependencies');
 launch_projection:=jsonb_build_object('targetSlug',c.slug,'competitionId',cid,'sourceCode',c.source_league_code,'season','2026/27','sourceFingerprintSha256',rec.source_fingerprint,'writerCommit',a->>'sourceCommit','fixtures',(select jsonb_agg(f order by id)from pg_temp._fcf_expected),'mapping',(select jsonb_agg(m order by m->>'sourceMatchId')from jsonb_array_elements(mp->'fixtures')m),'native',native);
 projection_sha:=encode(sha256(convert_to(private_fcf_future_import.canonical_json(launch_projection),'UTF8')),'hex');
 expected_proposal:=jsonb_build_object('schemaVersion',1,'kind','fcf-future-launch-proposal','targetSlug',c.slug,'competitionId',cid,'season','2026/27','sourceCode',c.source_league_code,'sourceFingerprintSha256',rec.source_fingerprint,'writerCommit',a->>'sourceCommit','projectionSha256',projection_sha,'roundNumber',selected,'roundId',rid,'firstFantasyPlayedOn',opening,'timeZone','Europe/Madrid','earliestKickoffUTC',to_char(earliest at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'deadlineUTC',to_char(deadline at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'fixtureIds',(select jsonb_agg(id order by id)from pg_temp._fcf_expected where rn=selected),'matchIds',(select jsonb_agg(mid order by mid)from pg_temp._fcf_expected where rn=selected));
 perform private_fcf_six_target_release.require(proposal=expected_proposal,'same frozen future proposal/projection; never replace an expired choice');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(readiness,array['modelSha256','pricingSnapshotText','pricingSnapshotSha256','priceVector','squad','cheapestLegal15','launchProposal'])and jsonb_typeof(readiness->'pricingSnapshotText')='string'and jsonb_typeof(readiness->'pricingSnapshotSha256')='string'and jsonb_typeof(readiness->'modelSha256')='string'and readiness->'launchProposal'=proposal and readiness->>'modelSha256'~'^[a-f0-9]{64}$','closed same-proposal readiness/model identity');
 price_text:=projection#>>'{pricingSnapshot,snapshotText}';
 perform private_fcf_six_target_release.require(readiness->>'pricingSnapshotText'=price_text and readiness->>'pricingSnapshotSha256'=projection#>>'{pricingSnapshot,snapshotSha256}'and encode(sha256(convert_to(price_text,'UTF8')),'hex')=readiness->>'pricingSnapshotSha256','exact persisted pricing dependency TEXT/SHA');
 perform private_fcf_six_target_release.require(not exists(with actual as(select jsonb_build_object('id',id,'value',value,'value_start',value_start,'position',position,'position_source',position_source)j from players where competition_id=cid),expected as(select value j from jsonb_array_elements(readiness->'priceVector'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual)),'actual full persisted price/provenance vector');
 perform private_fcf_six_target_release.require((select count(*)from private_fcf_six_target_release.club_bindings where competition_id=cid)=16 and not exists(select 1 from pg_temp._fcf_clubs n left join private_fcf_six_target_release.club_bindings b on b.competition_id=cid and b.club_id=n.club and b.category_id=n.category and b.team_id=n.team and b.country_id=c.country_id and b.source_fingerprint=rec.source_fingerprint where b.team_id is null)and not exists(select 1 from players where competition_id=cid and active and team_id not in(select team from pg_temp._fcf_clubs))and not exists(select 1 from pg_temp._fcf_clubs n where not exists(select 1 from pg_temp._fcf_apps e join players p on p.competition_id=cid and p.reg_st=e.reg where e.team=n.team and p.team_id=n.team and p.active and p.position='GK'and p.position_source='zapisnik'and(e.x->>'vratar')::boolean and(e.x->>'zacetnik')::boolean)),'actual sixteen clubs/active explicit official keeper coverage');
 perform private_fcf_six_target_release.require(not exists(select 1 from players where competition_id=cid and(value is null or value<=0 or value::text in('NaN','Infinity','-Infinity')or value_start::text in('NaN','Infinity','-Infinity'))),'finite complete persisted price vector');
 prices:=public.stanje_lige(cid);cost:=public.najcenejsi_kader(prices->'igralci');
 perform private_fcf_six_target_release.require((prices->>'klubov')::int=16 and cost is not null and cost<=100 and(readiness->>'cheapestLegal15')::numeric=cost and(prices->>'najvisja_cena')::numeric>=8 and coalesce((prices->>'privzetih')::numeric/nullif((prices->>'aktivnih')::numeric,0),1)<=0.7 and(prices->>'golov_brez_nastopa')::int=0,'actual varied prices and affordable legal15');
 perform private_fcf_six_target_release.require(jsonb_array_length(readiness->'squad')=15 and(select count(distinct(x->>'id')::bigint)from jsonb_array_elements(readiness->'squad')x)=15 and not exists(select 1 from jsonb_array_elements(readiness->'squad')x where not private_fcf_future_import.keys(x,array['id'])or not exists(select 1 from jsonb_array_elements(prices->'igralci')p where p->'id'=x->'id'))and(select sum((p->>'value')::numeric)from jsonb_array_elements(prices->'igralci')p where(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(readiness->'squad')x))<=100,'unique actual affordable witness');
 perform private_fcf_six_target_release.require(not exists(select p->>'team_id'from jsonb_array_elements(prices->'igralci')p where(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(readiness->'squad')x)group by p->>'team_id'having count(*)>3)and not exists(select q.position from(values('GK',2),('DEF',5),('MID',5),('FWD',3))q(position,n)where(select count(*)from jsonb_array_elements(prices->'igralci')p where p->>'position'=q.position and(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(readiness->'squad')x))<>q.n),'legal15 actual quotas and club limit');
 result:=jsonb_build_object('stage',case when p_activate then 'activated'else 'checked'end,'targetSlug',c.slug,'receiptId',rec.id::text,'activationSha256',p_sha256,'targetPacketSha256',rec.packet_sha256,'sourceFingerprintSha256',rec.source_fingerprint,'firstFantasyRound',selected,'firstFantasyPlayedOn',opening,'deadlineAt',deadline,'active',p_activate,'cheapestLegal15',cost);
 if not p_activate then if cid=783 then perform private_fcf_six_target_release.require(private_fcf_future_target_release.g9_image()=other_image,'G1 check/activation preserves G9 afterimage/receipt');end if;return result;end if;
 select jsonb_agg(to_jsonb(p)order by id)into protected_players from players p where competition_id=cid;
 select to_jsonb(i)into protected_policy from private_historical_statistics.installed_policies i where competition_id=cid;
 select encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')into protected_cleanup from private_fcf_future_history.cleanup_receipt r where singleton;
 expected_competition:=(native->'competition')||jsonb_build_object('prvi_fantasy_krog',selected,'active',true);
 select jsonb_agg(case when(r->>'id')::bigint=rid then r||jsonb_build_object('played_on',opening,'deadline_at',deadline)else r end order by(r->>'id')::bigint)into expected_rounds from jsonb_array_elements(native->'rounds')r;
 perform private_fcf_six_target_release.require(deadline>clock_timestamp(),'approved official deadline expired before activation');
 update competitions set prvi_fantasy_krog=selected where id=cid and not active;
 update rounds set played_on=opening,deadline_at=deadline where id=rid and lineups_locked_at is null and deadline_at>clock_timestamp();perform private_fcf_six_target_release.require(found,'never reopen expired/locked selected round');
 update private_historical_statistics.installed_policies set first_fantasy_played_on=opening where competition_id=cid;
 perform private_historical_statistics.authorize_release(cid,packet#>>'{target,policyId}',packet#>>'{target,policySha256}',p_sha256);update competitions set active=true where id=cid and not active;
 select jsonb_build_object('competition',(select to_jsonb(co)from competitions co where id=cid),'rounds',(select jsonb_agg(to_jsonb(r)order by id)from rounds r where competition_id=cid),'matches',(select jsonb_agg(to_jsonb(m)order by m.id)from matches m join rounds r on r.id=m.round_id where r.competition_id=cid))into after_native;
 perform private_fcf_six_target_release.require(after_native=jsonb_build_object('competition',expected_competition,'rounds',expected_rounds,'matches',native->'matches')and(select jsonb_agg(to_jsonb(p)order by id)from players p where competition_id=cid)=protected_players and(select to_jsonb(i)from private_historical_statistics.installed_policies i where competition_id=cid)=protected_policy||jsonb_build_object('first_fantasy_played_on',opening)and(select encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')from private_fcf_future_history.cleanup_receipt r where singleton)=protected_cleanup and deadline>clock_timestamp(),'same-TX exact intended opening/active afterimage and protected data');
 perform private_fcf_future_import.markers();perform private_fcf_six_target_release.compare_canonical(cid);after_image:=private_fcf_future_activation.after_image(cid);
 update private_fcf_future_target_release.receipts set stage='activated',activation_result=jsonb_build_object('activationText',p_activation_text,'activationSha256',p_sha256,'result',result,'afterImage',after_image)where id=rec.id;
 perform private_fcf_six_target_release.require(found and exists(select 1 from private_fcf_future_target_release.receipts where id=rec.id and stage='activated'and activation_result->>'activationSha256'=p_sha256 and activation_result->'afterImage'=private_fcf_future_activation.after_image(cid)),'saved activation receipt/afterimage readback');if cid=783 then perform private_fcf_six_target_release.require(private_fcf_future_target_release.g9_image()=other_image,'G1 check/activation preserves G9 afterimage/receipt');end if;return result;
end$$;

revoke all on all tables in schema private_fcf_g1_supplement from public,anon,authenticated,service_role;
revoke all on all functions in schema private_fcf_g1_supplement from public,anon,authenticated,service_role;
